import * as THREE from 'three/webgpu';
import { Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load the ceramic grain texture
  const textureMap = ctx.textureLoader.load(config.assets.imageUrl);
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with 512:320 aspect ratio
  const aspectRatio = 512 / 320;
  const width = 0.8;
  const height = width / aspectRatio;
  const geometry = new PlaneGeometry(width, height);

  // Create material with TSL texture node
  const colorNode = texture(textureMap);
  const material = new MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
  });

  // Create plane mesh
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Render text content "Features 3"
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.render(config.textContent, {
      size: 39,
      weight: 400,
      font: 'Lora',
      color: config.colors.ink,
      align: 'center',
      vAlign: 'center',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Apply position, rotation, and scale from config
  group.position.set(config.position[0], config.position[1], config.position[2]);
  group.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  group.scale.set(config.scale[0], config.scale[1], config.scale[2]);

  // Attach billboard handler for camera-facing updates
  group.userData.handlers = {
    updateBillboard: (camera) => {
      group.lookAt(camera.position);
    },
  };

  // Cleanup function for resource disposal
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textureMap) {
      textureMap.dispose();
    }
  };

  return group;
}
